import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.Dg5fKO7V.js";const p=JSON.parse('{"title":"Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"Changelog.md","filePath":"Changelog.md","lastUpdated":1788563284000}'),n={name:"Changelog.md"};function s(h,e,i,d,l,c){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><p>Release notes live with the code, so they are versioned alongside what they describe and can never drift from the tag they belong to.</p><ul><li><strong><a href="https://github.com/xeidral/anisphere/blob/main/CHANGELOG.md" target="_blank" rel="noreferrer">CHANGELOG.md</a></strong> covers every release, newest first.</li><li><strong><a href="https://github.com/xeidral/anisphere/releases" target="_blank" rel="noreferrer">Releases</a></strong> carries the installers and the signed update manifest for each version.</li></ul><h2 id="versioning" tabindex="-1">Versioning <a class="header-anchor" href="#versioning" aria-label="Permalink to &quot;Versioning&quot;">​</a></h2><p>AniSphere follows semantic versioning. The major number moves when something a user or a packager depends on changes shape: the licence, the IPC surface, the on-disk layout, or the update channel. The minor number moves for features, the patch number for fixes.</p><p>Three files carry the version and must always agree, which the release workflow enforces before it builds anything:</p><table tabindex="0"><thead><tr><th>File</th><th>Read by</th></tr></thead><tbody><tr><td><code>package.json</code></td><td>The frontend build and the release tag check</td></tr><tr><td><code>src-tauri/Cargo.toml</code></td><td>The Rust crate</td></tr><tr><td><code>src-tauri/tauri.conf.json</code></td><td>The bundler, and through it the updater&#39;s version comparison</td></tr></tbody></table><p>A mismatch here ships installers whose version disagrees with the tag, which breaks the update check for everyone who already has the app.</p>',8)])])}const u=t(n,[["render",s]]);export{p as __pageData,u as default};
